#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeForge: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = Forge

    public static func lift(_ handle: UInt64) throws -> Forge {
        return Forge(unsafeFromHandle: handle)
    }

    public static func lower(_ value: Forge) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Forge {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: Forge, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
