        self.modeLine = modeLine
        self.selected = selected
        self.border = border
        self.gutter = gutter
        self.headerRows = headerRows
        self.scrollYPx = scrollYPx
        self.hlRows = hlRows
        self.fillColumn = fillColumn
        self.fillColumnCharacter = fillColumnCharacter
        self.popup = popup
