        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_forge_ffi_checksum_method_forge_save_session() != 1155) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_forge_ffi_checksum_method_forge_scroll_pixels() != 49011) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_forge_ffi_checksum_method_forge_scroll_to_column() != 8944) {
